  const term = () => { let v = pow(); while (peek() === "*" || peek() === "/") { const o = t[i++], b = pow(); v = o === "*" ? v * b : v / b; } return v; };
  const expr = () => { let v = term(); while (peek() === "+" || peek() === "-") { const o = t[i++], b = term(); v = o === "+" ? v + b : v - b; } return v; };
