    const n = +b.dataset.imkgo, words = B.querySelector(`[data-imk="${n}"]`).value.split(/[,;]+/).map(w => w.trim().toUpperCase()).filter(Boolean); if (!words.length) return toast("Type a word the pages should have, e.g. PLAN", 2500);
