    if (!S.geo[pk]) { if (S.key !== pk) await gotoPage(fid, pg); for (let n = 0; n < 100 && !S.geo[pk]; n++) await new Promise(r => setTimeout(r, 100)); }
    const g = S.geo[pk]; if (!g || !g.segs || g.segs.length < 50) return [];
