  RAL = o && Array.isArray(o.items) && Array.isArray(o.rates) ? {o, t: Date.now(), items: new Map(o.items.map(i => [String(i.code || i.id).toUpperCase(), i])), rates: new Map(o.rates.map(r => [r.code, r]))} : {o: null, t: Date.now()};
