      if (fil) { const r = num("fcR"); return r >= 0 && isFinite(r) ? {r} : "Enter a radius, e.g. 1.5 or 6\""; }
      const d1 = num("fcA"), d2 = num("fcB"); return d1 >= 0 && d2 >= 0 && isFinite(d1 + d2) ? {d1, d2} : "Enter distances in feet, e.g. 0.5";
