  setSel([A.it.id]); refresh();
  toast((kind === "fillet" ? "Filleted" : "Chamfered") + " — the two runs are now one: " + f3(polyLen(out) / k) + " ft in " + (cond(A.it.cond) || {name: "its condition"}).name, 3200);
