    if (!k) { skipped++; return; }
    const L = lname(c), q = rowsOf(it, k).reduce((a, r) => a + r.qty, 0), lab = (it.label ? it.label + " " : "") + c.name + " " + fq(q, c.unit) + " " + c.unit;
