    if (d.type === "string" && typeof v !== "string") a[k] = String(v);
    if (d.type === "array" && !Array.isArray(v)) return k + " must be a list";
    if (d.enum && !d.enum.includes(a[k])) return k + " must be one of " + d.enum.join(", ");
