      const geo = sg * nos * Fs * (c.type === "area" ? polyArea(poly) / s.k / s.k : (it.shape === "circle" ? polyLen(poly, true) : polyLen(it.pts)) / s.k) + (c.type === "linear" ? rows.filter(r => r.rise).reduce((a, r) => a + r.qty, 0) : 0);
