  const scope = /\b(selected|ticked|chosen)\b/.test(t) ? "sel" : /\b(with|having)\s+(?:the\s+)?(?:takeoff|measurements?|markups?)\b|\bmarked[\s-]*up\b|\bmeasured\b/.test(t) ? "tk" : /\b(all|every|whole)\b/.test(t) ? "all" : "page", dm = /(\d{2,3})\s*dpi\b/.exec(t);
