  if (/mini\s*-?\s*map/.test(t)) { const on = /\boff\b|\bhide\b/.test(t) ? false : /\bon\b|\bshow\b/.test(t) ? true : !wsPref().mini; wsSet({mini: on}); return aiLog("bot", "Minimap " + (on ? "on — it shows when you zoom in." : "off.")); }
